$pageTitle='Личный кабинет — Лесная гавань';$st = $pdo->prepare('SELECT b.*,a.title,a.type,a.image FROM bookings b JOIN accommodations a ON a.id = b.accommodation_id WHERE b.user_id = ? ORDER BY b.created_at DESC');$st->execute([$user['id']]);$bookings=$st->fetchAll();
